class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars are no longer treated as unset.
        // Previously GetEnvironmentVariable("MY_FLAG") returned null for export MY_FLAG="".
        // Now it correctly returns "" — so use a dedicated method to distinguish "not set" vs "empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (!IsEnvironmentVariableSet("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool IsEnvironmentVariableSet(string variable)
    {
        // On .NET 9+, GetEnvironmentVariable returns "" for explicitly empty vars
        // and null only when the variable is truly not set.
        return Environment.GetEnvironmentVariable(variable) != null;
    }
}

